package com.example.cloud.auth

import android.content.Context

/**
 * Resolves the OAuth web client ID generated by the Google Services Gradle plugin
 * from `app/google-services.json` (`R.string.default_web_client_id`).
 *
 * The resource only exists when the plugin has run against a `google-services.json`.
 * Looking it up by name keeps debug builds without that file compiling, while still
 * returning the generated value whenever one is present.
 */
object GoogleWebClientId {

    private const val RESOURCE_NAME = "default_web_client_id"

    fun resolve(context: Context): String? {
        val resourceId = context.resources.getIdentifier(
            RESOURCE_NAME,
            "string",
            context.packageName
        )
        if (resourceId == 0) return null
        return runCatching { context.getString(resourceId) }
            .getOrNull()
            ?.takeIf { it.isNotBlank() }
    }
}
